const express = require('express');
const { Server } = require('@tus/server');
const { FileStore } = require('@tus/file-store');
const { authenticateApiKey } = require('../auth');

const router = express.Router();
const tusServer = new Server({
  path: '/iot/firmware/uploads',
  datastore: new FileStore({ directory: './firmware_bins' })
});

router.delete('/iot/firmware/uploads/:uploadId', authenticateApiKey, async (req, res) => {
  const uploadId = req.params.uploadId;
  const upload = await tusServer.datastore.getUpload(uploadId);
  if (!upload) return res.status(404).json({ error: 'Upload not found' });

  if (upload.metadata?.manufacturerId !== req.apiKeyData.manufacturerId) {
    return res.status(403).json({ error: 'Forbidden: upload belongs to another manufacturer' });
  }

  await tusServer.datastore.delete(uploadId);
  res.status(204).end();
});
